import sys, random
sys.path.insert(0,'/tmp')
from randprobe import is_rand
random.seed(1)
alpha="abcdABCD12"
vals=[]
for _ in range(800):
    vals.append("".join(random.choice(alpha) for _ in range(14)))
# deduplicate
vals=list(dict.fromkeys(vals))
r=is_rand(vals)
from collections import defaultdict, Counter
def bigramkey(s):
    return (tuple(sorted(Counter(s).items())), tuple(sorted(Counter(s[i:i+2] for i in range(len(s)-1)).items())))
def unigramkey(s): return tuple(sorted(Counter(s).items()))
groups=defaultdict(list)
for s,b in zip(vals,r): groups[bigramkey(s)].append((s,b))
discord=[g for g in groups.values() if len(set(b for _,b in g))>1]
print("bigram groups total", len(groups), "multi", sum(1 for g in groups.values() if len(g)>1), "discord", len(discord))
for g in discord[:20]: print(g)
# unigram discord count
groups=defaultdict(list)
for s,b in zip(vals,r): groups[unigramkey(s)].append((s,b))
discord=[g for g in groups.values() if len(set(b for _,b in g))>1 and len(g)>1]
print("unigram groups multi discord", len(discord), "multi total", sum(1 for g in groups.values() if len(g)>1))
for g in discord[:10]: print(g)
