{"command":"python3 << 'PY'
import sys,os,tempfile
sys.path.insert(0,'/tmp')
from install_probe import run, showfile
hook="ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`"
for content in [f"x{hook}\n", f"{hook}x\n", f"x{hook}x\n", f"{hook}\r\n", f" {hook}\n", f"{hook} \n", f"{hook}\nfoo\n", f"foo\n{hook}", f"{hook}\n{hook}\n"]:
    td=tempfile.mkdtemp(); os.makedirs(td+"/.git/hooks"); open(td+"/.git/hooks/pre-commit",'w').write(content)
    run(td,["--install-pre-commit"]); showfile(td+"/.git/hooks/pre-commit")
# pre-commit is directory, symlink, unreadable etc
for kind in ["dir","symlink_missing","symlink_target","readonlyfile","nonutf8"]:
    td=tempfile.mkdtemp(); os.makedirs(td+"/.git/hooks")
    p=td+"/.git/hooks/pre-commit"
    if kind=="dir": os.makedirs(p)
    elif kind=="symlink_missing": os.symlink("missingtarget",p)
    elif kind=="symlink_target": open(td+"/target",'w').write("hi\n"); os.symlink(td+"/target",p)
    elif kind=="readonlyfile": open(p,'w').write("hi\n"); os.chmod(p,0o444)
    elif kind=="nonutf8": open(p,'wb').write(b"\xff\xfe\n")
    print(kind); run(td,["--install-pre-commit"]); showfile(p)
# combination with secret and scan?
