import subprocess, os, tempfile
EXE=os.path.abspath("./executable")
def flags(vals):
    with tempfile.TemporaryDirectory() as td:
        p=os.path.join(td,"x.txt"); open(p,'w',encoding='utf-8').write("\n".join("ZZ:"+v+" END" for v in vals)+"\n")
        r=subprocess.run([EXE,p,"--additional-pattern",r"ZZ:(\S+)","--only-matching"],capture_output=True,text=True)
        matched=set()
        for l in r.stdout.splitlines():
            try: matched.add(int(l[len(p)+1:].split(':',1)[0]))
            except: pass
        return [i+1 in matched for i in range(len(vals))], r.returncode, r.stderr
def range_str(base, maxlen):
    vals=[base*L for L in range(1,maxlen+1)]
    f,rc,err=flags(vals)
    # summarize ranges
    ranges=[]; start=1; cur=f[0]
    for i,b in enumerate(f[1:],2):
        if b!=cur: ranges.append(f"{start}-{i-1}:{'R' if cur else '.'}"); start=i;cur=b
    ranges.append(f"{start}-{maxlen}:{'R' if cur else '.'}")
    return ",".join(ranges)
