{"command":"python3 << 'PY' > /tmp/out.txt
import sys,random; sys.path.insert(0,'/tmp')
from randcompact import flags
from collections import defaultdict, Counter
random.seed(7)
alpha="abcd"
bases=[]
for _ in range(500):
    bases.append("".join(random.choice(alpha) for _ in range(12)))
f0,_,_=flags(bases)
def alt(s):
    adj=defaultdict(list)
    for a,b in zip(s,s[1:]): adj[a].append(b)
    for a in adj: random.shuffle(adj[a])
    stack=[s[0]]; path=[]; local={k:list(v) for k,v in adj.items()}
    while stack:
        v=stack[-1]
        if local.get(v): stack.append(local[v].pop())
        else: path.append(stack.pop())
    t="".join(path[::-1])
    return t if len(t)==len(s) and Counter(zip(s,s[1:]))==Counter(zip(t,t[1:])) and t!=s else None
pairs=[]
for s,b in zip(bases,f0):
    alts=set()
    for _ in range(30):
        t=alt(s)
