from randcompact import flags
from collections import Counter
random.seed(0)
# create closed trails: random walk returning to start by construction (concatenate cycles a->X->a etc) but maybe bases all non. use random Eulerian circuit on complete-ish multigraph with edges randomly paired cycles of length 3: x->y->z->x concatenating cycles sharing vertices can still represent.
def make(alpha, ncycles):
    s=alpha[0]
    cur=s
    out=[cur]
    for _ in range(ncycles):
        a,b=random.sample(alpha,2)
        # path cur->a->b->cur
