{"command":"mkdir -p /tmp/fit && cat > /tmp/fit/main.rs << 'RS'
use std::collections::HashMap;
use std::fs;
#[derive(Clone)]
struct Sample{ y:f64, feats:Vec<(usize,f64)> }
fn load(path:&str, use_end:bool, use_len:bool, use_loglen:bool, use_start:bool, use_unigram:bool)->Vec<Sample>{
 let txt=fs::read_to_string(path).unwrap();
 let mut out=Vec::new();
 for line in txt.lines(){
   let mut it=line.splitn(2,'\t'); let y: f64=it.next().unwrap().parse().unwrap(); let s=it.next().unwrap_or("");
   let b=s.as_bytes(); let mut m:HashMap<usize,f64>=HashMap::new();
   *m.entry(0).or_default()+=1.0;
   if !b.is_empty() {
     if use_start { *m.entry(1+b[0] as usize).or_default()+=1.0; }
     if use_end { *m.entry(257+b[b.len()-1] as usize).or_default()+=1.0; }
   }
   for w in b.windows(2){ *m.entry(513+(w[0] as usize)*256+(w[1] as usize)).or_default()+=1.0; }
   if use_unigram { for &c in b { *m.entry(513+65536+(c as usize)).or_default()+=1.0; } }
   if use_len { *m.entry(513+65536+256).or_default()+= b.len() as f64; }
   if use_loglen { *m.entry(513+65536+257).or_default()+= (b.len() as f64).ln(); }
   // Extra basis always after: n log n, sqrt n as two features indices beyond
   *m.entry(513+65536+258).or_default()+= (b.len() as f64)*((b.len() as f64).ln());
   *m.entry(513+65536+259).or_default()+= (b.len() as f64).sqrt();
   out.push(Sample{y, feats:m.into_iter().collect()});
 }
 out
}
fn score(w:&[f64],s:&Sample)->f64{s.feats.iter().map(|(i,v)|w[*i]*v).sum()}
fn eval(w:&[f64],data:&[Sample])->(f64,f64){
 let mut correct=0; let mut loss=0.0;
 for s in data{ let z=score(w,s); let p=1.0/(1.0+(-z).exp()); if (p>=0.5)==(s.y>0.5){correct+=1;} loss+= if s.y>0.5{-p.max(1e-12).ln()}else{-(1.0-p).max(1e-12).ln()}; }
 (correct as f64/data.len() as f64, loss/data.len() as f64)
}
fn main(){
 let args:Vec<String>=std::env::args().collect();
