use std::collections::HashMap; use std::fs;
#[derive(Clone)] struct Sample{y:f64, feats:Vec<(usize,f64)>}
const BIG:usize=1000;
fn load(path:&str, mode:u64)->Vec<Sample>{
 let txt=fs::read_to_string(path).unwrap(); let mut out=Vec::new();
 for line in txt.lines(){ let mut it=line.splitn(2,'\t'); let y:f64=it.next().unwrap().parse().unwrap(); let s=it.next().unwrap_or(""); let b=s.as_bytes(); let n=b.len();
  let mut m:HashMap<usize,f64>=HashMap::new(); *m.entry(0).or_default()+=1.0;
  // length one-hot 1..128 (mode>=1)
  if mode>=1 { *m.entry(1+n.min(127)).or_default()+=1.0; }
  if !b.is_empty(){ *m.entry(200+b[0] as usize).or_default()+=1.0; *m.entry(500+b[b.len()-1] as usize).or_default()+=1.0; }
  for w in b.windows(2){ *m.entry(BIG+(w[0] as usize)*256+(w[1] as usize)).or_default()+=1.0; }
  out.push(Sample{y,feats:m.into_iter().collect()});
 } out
}
fn score(w:&[f64],s:&Sample)->f64{s.feats.iter().map(|(i,v)|w[*i]*v).sum()}
fn eval(w:&[f64],d:&[Sample])->(f64,f64){let mut c=0;let mut l=0.0;for s in d{let z=score(w,s);let p=1.0/(1.0+(-z).exp());if(p>=0.5)==(s.y>0.5){c+=1;}l+=if s.y>0.5{-p.max(1e-12).ln()}else{-(1.0-p).max(1e-12).ln()};}(c as f64/d.len() as f64,l/d.len() as f64)}
fn main(){
 let mode:u64=std::env::args().nth(1).unwrap_or("1".into()).parse().unwrap();
 let train=load("/tmp/train.tsv",mode); let test=load("/tmp/test.tsv",mode);
 let nfeat=BIG+65536; let mut w=vec![0.0;nfeat]; let mut gacc=vec![0.0;nfeat];
 let mut seed=42u64; let mut idx:Vec<usize>=(0..train.len()).collect();
 for epoch in 0..80{
  for i in (1..idx.len()).rev(){seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);idx.swap(i,((seed>>32)as usize)%(i+1));}
  for &ii in &idx{let s=&train[ii];let z=score(&w,s);let p=1.0/(1.0+(-z).exp());let g=p-s.y;
   for(fi,v) in &s.feats{let grad=g*v+0.00003*w[*fi];gacc[*fi]+=grad*grad;w[*fi]-=0.5*grad/(gacc[*fi].sqrt()+1e-8);}
  }
  if epoch%10==9{let(a,l)=eval(&w,&train);let(ta,tl)=eval(&w,&test);println!("ep{} train {:.4}/{:.3} test {:.4}/{:.3}",epoch,a,l,ta,tl);}
 }
 let mut out=String::new();for(i,v) in w.iter().enumerate(){if v.abs()>1e-9{out.push_str(&format!("{}\t{}\n",i,v));}}fs::write("/tmp/weights3.txt",out).unwrap();
}
