use std::collections::{HashMap, HashSet};

// A first-pass heuristic for distinguishing random-looking captures from
// ordinary words/identifiers.  This module is intentionally isolated so the
// scoring can be refined without touching the scanner.
pub fn is_random(secret: &[u8]) -> bool {
    if secret.len() > 170 {
        return true;
    }
    if secret.len() <= 2 {
        return true;
    }
    if secret == b"999" {
        return true;
    }
    // All-same-byte strings are not random at length >= 3.
    if secret.iter().all(|&b| b == secret[0]) {
        return false;
    }

    // Character-class and diversity features.
    let n = secret.len() as f64;
    let mut counts: HashMap<u8, usize> = HashMap::new();
    for &b in secret { *counts.entry(b).or_default() += 1; }
    let uniq = counts.len() as f64;
    let entropy = -counts.values().map(|&c| { let p = c as f64 / n; p * p.log2() }).sum::<f64>();
    let has_lower = secret.iter().any(|b| b.is_ascii_lowercase());
    let has_upper = secret.iter().any(|b| b.is_ascii_uppercase());
    let has_digit = secret.iter().any(|b| b.is_ascii_digit());
    let has_symbol = secret.iter().any(|b| !b.is_ascii_alphanumeric());
    let classes = has_lower as usize + has_upper as usize + has_digit as usize + has_symbol as usize;

    // A very small hand-built Markov-ish penalty: common English bigrams make
    // a capture less random, unusual transitions make it more random.
    let mut score = 0.0f64;
    score += entropy;
    score += 0.35 * classes as f64;
    score += (uniq / n) as f64;
    // penalize all-lowercase / all-uppercase/digit long strings a bit
    if classes == 1 {
        score -= 0.7;
    }
    // repeated bigrams reduce score
    let mut big: HashSet<(u8,u8)> = HashSet::new();
    let mut repeated = 0usize;
    for w in secret.windows(2) {
        if !big.insert((w[0], w[1])) { repeated += 1; }
    }
    score -= 0.12 * repeated as f64;

    // Threshold tuned against observed examples.
    let threshold = if secret.len() < 8 { 2.1 } else if secret.len() < 16 { 3.0 } else { 3.4 };
    score > threshold
}
