                        }
                    }
                }
                Err(err) => {
                    eprintln!("{}", err);
                }
            }
            WalkState::Continue
        })
    });

    Ok(ctx.found.load(Ordering::SeqCst))
}

fn main() {
    let cli = parse_cli();
    match run(cli) {
        Ok(found) => {
            if found {
                std::process::exit(1);
            }
        }
        Err(err) => {
            eprintln!("Error: {}", err);
            std::process::exit(2);
        }
    }
}
