    r"https://hooks\.slack\.com/services/T[\dA-Za-z_]+/B[\dA-Za-z_]+/[\dA-Za-z_]+",
    r"SG\.[\dA-Za-z_-]{22}\.[\dA-Za-z_-]{43}",
    r"(?:AC|SK)[\da-z]{32}",
    r"[\da-f]{32}-us\d{1,2}",
    r"s-s4t2(?:af|ud)-[\da-f]{64}",
    r"PuTTY-User-Key-File-2",
    r"AGE-SECRET-KEY-1[\dA-Z]{58}",
    r"-{5}BEGIN DSA PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)",
    r"-{5}BEGIN EC PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)",
    r"-{5}BEGIN OPENSSH PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)",
    r"-{5}BEGIN PGP PRIVATE KEY BLOCK-{5}(?:$|[^-]{63,}-{5}END)",
    r"-{5}BEGIN PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)",
    r"-{5}BEGIN RSA PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)",
    r"-{5}BEGIN SSH2 ENCRYPTED PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)",
    r#"(?i:key|token|secret|password)\w*["']?]?\s*(?:[:=]|:=|=>|<-|>)\s*[\t "'`]?([\w+./=~\-\\`^]{15,90})(?:[\t\n "'`]|</|$)"#,
];

struct Cli {
    paths: Vec<PathBuf>,
    install_pre_commit: bool,
    strict_ignore: bool,
    only_matching: bool,
    additional_patterns: Vec<String>,
}

fn build_cli() -> Command {
    Command::new("ripsecrets")
        .version("0.1.11")
        .about(SHORT_ABOUT)
        .long_about(LONG_ABOUT)
        .arg(
            Arg::new("paths")
                .help("Source files. Can be files or directories. Defaults to '.'")
                .long_help("Source files. Can be files or directories. Defaults to '.'")
                .value_name("Source files")
                .action(ArgAction::Append)
                .num_args(0..),
        )
        .arg(
            Arg::new("install_pre_commit")
                .long("install-pre-commit")
                .help("Install `ripsecrets` as a pre-commit hook automatically in git directory provided")
                .long_help("Install `ripsecrets` as a pre-commit hook automatically in git directory provided")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("strict_ignore")
                .long("strict-ignore")
                .help("If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit")
                .long_help("If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("only_matching")
                .long("only-matching")
                .help("Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line")
                .long_help("Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("additional_patterns")
                .long("additional-pattern")
                .help("Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret")
                .long_help("Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret")
                .action(ArgAction::Append)
                .num_args(1),
        )
}

fn parse_cli() -> Cli {
    let matches = build_cli().get_matches();
    let paths = matches
        .get_many::<String>("paths")
        .map(|vals| vals.map(PathBuf::from).collect())
        .unwrap_or_default();
    let additional_patterns = matches
        .get_many::<String>("additional_patterns")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();
    Cli {
        paths,
        install_pre_commit: matches.get_flag("install_pre_commit"),
        strict_ignore: matches.get_flag("strict_ignore"),
        only_matching: matches.get_flag("only_matching"),
        additional_patterns,
    }
}

struct SecretsIgnore {
    ignore_file: Option<PathBuf>,
    ignored_secrets: HashSet<Vec<u8>>,
    // Keep the temp file alive until the walk has finished.
    _temp_file: Option<NamedTempFile>,
}

fn load_secretsignore() -> Result<SecretsIgnore> {
    let cwd = std::env::current_dir()?;
    let path = cwd.join(".secretsignore");
    if !path.exists() {
        return Ok(SecretsIgnore { ignore_file: None, ignored_secrets: HashSet::new(), _temp_file: None });
    }
    let contents = std::fs::read_to_string(&path)?;
    let split: Vec<&str> = contents.split("[secrets]\n").collect();
    if split.len() > 1 {
        let ignored_secrets = split[1]
            .split('\n')
            .filter(|s| !s.is_empty())
            .map(|s| s.as_bytes().to_vec())
            .collect();
        let mut temp = NamedTempFile::new()?;
        temp.write_all(split[0].as_bytes())?;
        temp.flush()?;
        let temp_path = temp.path().to_path_buf();
        Ok(SecretsIgnore { ignore_file: Some(temp_path), ignored_secrets, _temp_file: Some(temp) })
    } else {
        Ok(SecretsIgnore { ignore_file: Some(path), ignored_secrets: HashSet::new(), _temp_file: None })
    }
}

fn build_regex(additional: &[String]) -> Result<Regex> {
    let mut all: Vec<&str> = PATTERNS.to_vec();
    for pat in additional {
        all.push(pat.as_str());
    }
    let joined = format!("({})", all.join("|"));
    Ok(Regex::new(&joined)?)
}

fn build_strict_matcher(ignore_file: &Path, cwd: &Path) -> Gitignore {
    let mut builder = GitignoreBuilder::new(cwd);
    builder.allow_unclosed_class(false);
    let _ = builder.add(ignore_file);
    builder.build().unwrap_or_else(|_| Gitignore::empty())
}

fn is_strict_ignored(matcher: &Gitignore, path: &Path) -> bool {
    // Test the path and each parent, like Gitignore::matched_path_or_any_parents,
    // but without panicking for paths outside the matcher root.
    let mut current: Option<&Path> = Some(path);
    let mut first = true;
    while let Some(p) = current {
        let is_dir = if first { p.is_dir() } else { true };
        match matcher.matched(p, is_dir) {
            ignore::Match::Ignore(_) => return true,
            ignore::Match::Whitelist(_) => return false,
            ignore::Match::None => {}
        }
        first = false;
        current = p.parent();
        if let Some(c) = current {
            if c.as_os_str().is_empty() {
                // Match the empty parent once, then stop.
                match matcher.matched(c, true) {
                    ignore::Match::Ignore(_) => return true,
                    ignore::Match::Whitelist(_) => return false,
                    ignore::Match::None => {}
                }
                break;
            }
        }
    }
    false
}

struct SearchContext {
    regex: Regex,
    only_matching: bool,
    ignored_secrets: HashSet<Vec<u8>>,
    found: AtomicBool,
    stdout: Mutex<io::Stdout>,
}

impl SearchContext {
    fn write_output(&self, bytes: &[u8]) -> io::Result<()> {
        let mut out = self.stdout.lock().unwrap();
        out.write_all(bytes)?;
        out.flush()?;
        Ok(())
    }

    fn search_line(&self, path: &Path, line_no: u64, line: &[u8]) -> io::Result<()> {
        let mut secrets: Vec<&[u8]> = Vec::new();
        let mut pos = 0usize;
        while pos < line.len() {
            let Some(caps) = self.regex.captures_at(line, pos) else { break };
            let whole = caps.get(0).unwrap();
            // The first participating group after the outer wrapper group is
            // the secret (and is subject to the randomness check).
            let mut selected = whole;
            let mut has_group = false;
            for i in 2..caps.len() {
                if let Some(m) = caps.get(i) {
                    selected = m;
                    has_group = true;
                    break;
                }
            }
            let secret = selected.as_bytes();
            let accept = (!has_group || randomness::is_random(secret))
                && !self.ignored_secrets.contains(secret);
            if accept {
                secrets.push(secret);
            }
            if whole.end() == whole.start() {
                pos = whole.end() + 1;
            } else {
                pos = whole.end();
            }
        }
        if secrets.is_empty() {
            return Ok(());
        }
        self.found.store(true, Ordering::SeqCst);
        let path_bytes = path_bytes(path);
        if self.only_matching {
            for secret in secrets {
                let mut out = Vec::with_capacity(path_bytes.len() + secret.len() + 24);
                out.extend_from_slice(path_bytes);
                out.extend_from_slice(format!(":{}:", line_no).as_bytes());
                out.extend_from_slice(secret);
                out.push(b'\n');
                self.write_output(&out)?;
            }
        } else {
            let mut out = Vec::with_capacity(path_bytes.len() + line.len() + 24);
            out.extend_from_slice(path_bytes);
            out.extend_from_slice(format!(":{}:", line_no).as_bytes());
            out.extend_from_slice(line);
            out.push(b'\n');
            self.write_output(&out)?;
        }
        Ok(())
    }

    fn search_file(&self, path: &Path) -> io::Result<()> {
        let file = File::open(path)?;
        let mut reader = BufReader::new(file);
        // BOM sniffing, mirroring grep-style transcoding.
        let initial = reader.fill_buf()?.to_vec();
        if initial.starts_with(&[0xFF, 0xFE]) || initial.starts_with(&[0xFE, 0xFF]) {
            let mut raw = Vec::new();
            reader.read_to_end(&mut raw)?;
            let text = decode_utf16_with_bom(&raw);
            let bytes = text.as_bytes();
            let mut line_no: u64 = 0;
            for chunk in bytes.split(|&b| b == b'\n') {
                // split() yields a trailing empty piece for a final newline;
                // replicate line iteration by handling it below.
                line_no += 1;
                // The final empty chunk after a trailing newline is not a
                // real line; skip it if it is the very end.
                if chunk.is_empty() && line_no > 1 {
                    // We cannot cheaply know here whether this is a genuine
                    // blank line or the trailing split artifact without an
                    // index; blank lines never produce output, so skipping
                    // empty chunks is harmless except for line numbers of
                    // later lines (there are none after the trailing chunk).
                    // To keep numbers right for genuine blank lines in the
                    // middle, only skip when this is the last chunk.
                    // `split` in a for-loop hides that, so treat empty chunks
                    // as lines anyway:
                }
                self.search_line(path, line_no, chunk)?;
            }
            return Ok(());
        }
        let mut skip = 0usize;
        if initial.starts_with(&[0xEF, 0xBB, 0xBF]) {
            skip = 3;
        }
        if skip > 0 {
            reader.consume(skip);
        }
        let mut line_no: u64 = 0;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            buf.clear();
            let n = reader.read_until(b'\n', &mut buf)?;
            if n == 0 {
                break;
            }
            line_no += 1;
            let mut line: &[u8] = &buf;
            if line.last() == Some(&b'\n') {
                line = &line[..line.len() - 1];
            }
            // Own the line for the call duration (search_line borrows it).
            let owned = line.to_vec();
            self.search_line(path, line_no, &owned)?;
        }
        Ok(())
    }
}

fn decode_utf16_with_bom(raw: &[u8]) -> String {
    if raw.starts_with(&[0xFF, 0xFE]) {
        let units: Vec<u16> = raw[2..]
            .chunks_exact(2)
            .map(|c| u16::from_le_bytes([c[0], c[1]]))
            .collect();
        String::from_utf16_lossy(&units)
    } else if raw.starts_with(&[0xFE, 0xFF]) {
        let units: Vec<u16> = raw[2..]
            .chunks_exact(2)
            .map(|c| u16::from_be_bytes([c[0], c[1]]))
            .collect();
        String::from_utf16_lossy(&units)
    } else {
        String::from_utf8_lossy(raw).into_owned()
    }
}

fn path_bytes(path: &Path) -> &[u8] {
    #[cfg(unix)]
    {
        path.as_os_str().as_bytes()
    }
    #[cfg(not(unix))]
    {
        // Fallback: lossy conversion (not used on the target platform).
        Box::leak(path.to_string_lossy().into_owned().into_boxed_str()).as_bytes()
    }
}

fn print_path_error(path: &Path, err: &io::Error) {
    let mut stderr = io::stderr().lock();
    let _ = stderr.write_all(path_bytes(path));
    let _ = stderr.write_all(format!(": {}\n", err).as_bytes());
}

fn run(cli: Cli) -> Result<bool> {
    let mut paths = if cli.paths.is_empty() { vec![PathBuf::from(".")] } else { cli.paths.clone() };

    if cli.install_pre_commit {
        pre_commit::install(&paths)?;
        return Ok(false);
    }

    let secretsignore = load_secretsignore()?;
    let regex = build_regex(&cli.additional_patterns)?;

    if cli.strict_ignore {
        if let Some(ignore_file) = &secretsignore.ignore_file {
            let cwd = std::env::current_dir()?;
            let matcher = build_strict_matcher(ignore_file, &cwd);
            paths.retain(|p| !is_strict_ignored(&matcher, p));
        }
    }
    if paths.is_empty() {
        return Ok(false);
    }

    let ctx = Arc::new(SearchContext {
        regex,
        only_matching: cli.only_matching,
        ignored_secrets: secretsignore.ignored_secrets.clone(),
        found: AtomicBool::new(false),
        stdout: Mutex::new(io::stdout()),
    });

    let mut builder = WalkBuilder::new(&paths[0]);
    for p in &paths[1..] {
        builder.add(p);
    }
    if let Some(ignore_file) = &secretsignore.ignore_file {
        builder.add_custom_ignore_filename(ignore_file.as_os_str());
    }
    let walker = builder.build_parallel();
    walker.run(|| {
        let ctx = Arc::clone(&ctx);
        Box::new(move |result| {
            match result {
                Ok(entry) => {
                    let is_file = entry.file_type().map(|ft| ft.is_file()).unwrap_or(false);
                    if is_file {
                        if let Err(err) = ctx.search_file(entry.path()) {
                            print_path_error(entry.path(), &err);
                        }
                    }
                }
                Err(err) => {
                    eprintln!("{}", err);
                }
            }
            WalkState::Continue
        })
    });

    Ok(ctx.found.load(Ordering::SeqCst))
}

fn main() {
    let cli = parse_cli();
    match run(cli) {
        Ok(found) => {
            if found {
                std::process::exit(1);
            }
        }
        Err(err) => {
            eprintln!("Error: {}", err);
            std::process::exit(2);
        }
