from randcompact import flags
rng=random.Random(0)
def make(chars,counts,style):
    lst=[]
    if style=='block': lst=list(''.join(c*n for c,n in zip(chars,counts)))
    elif style=='roundrobin':
        # repeatedly cycle chars until counts exhausted
        rem=list(counts); out=[]
        while sum(rem)>0:
            for i,c in enumerate(chars):
                if rem[i]>0: out.append(c); rem[i]-=1
        lst=out
