import sys,random,string;sys.path.insert(0,'/tmp')
from randcompact import flags
rng=random.Random(0)
def vals_for(alpha,L,u,skew):
 # counts: one dominant = L-u+1 if skew max, balanced if skew None, intermediate dominant d
 counts=[]
 if skew is None:
  counts=[L//u]*u
  for i in range(L%u):counts[i]+=1
 else:
  counts=[skew]+[1]*(u-1); rem=L-sum(counts); i=1
  while rem>0:counts[i]+=1;rem-=1;i=1+(i%(u-1))
 vals=[]
 for _ in range(20):
  chars=rng.sample(alpha,u);lst=list(''.join(c*n for c,n in zip(chars,counts)));rng.shuffle(lst);vals.append(''.join(lst))
 return vals,counts
for alpha in [string.ascii_uppercase,string.digits,"0123456789abcdef",string.ascii_lowercase]:
 for L in [16,20,24]:
  for u in range(1,min(len(alpha),L)+1):
   for skew in [None, L-u+1]:
    vals,counts=vals_for(alpha,L,u,skew);f,_,_=flags(vals)
    print(alpha[:6],L,'u',u,'skew' if skew else 'bal',sum(f))
