import sys,itertools;sys.path.insert(0,'/tmp')
from randcompact import flags
from collections import Counter,defaultdict
for alpha in ['ab','AB','aB','01','a1']:
 for L in [8,12,16]:
  vals=[''.join(x) for x in itertools.product(alpha,repeat=L)]
  f,_,_=flags(vals)
  print(alpha,L,'R',sum(f),'/',len(vals))
  # group by (#a firstchar count, transitions/runs)
  def runs(s): return 1+sum(a!=b for a,b in zip(s,s[1:]))
  groups=defaultdict(lambda:[0,0])
  for s,b in zip(vals,f): groups[(s.count(alpha[0]),runs(s))][b]+=1
  # print matrix count_a rows, runs cols proportion R if any group not homogenous note counts of R/total
  for ca in range(L+1):
    row=[]
    for r in range(1,L+1):
        v=groups.get((ca,r))
        row.append('-' if not v else ('R' if v[0]==0 else '.' if v[1]==0 else f"{v[1]}/{sum(v)}"))
    print(' count',alpha[0],ca,row)
