{"command":"python3 << 'PY'
import math,random,string
from collections import Counter,defaultdict
rng=random.Random(0)
def smoothed_cond_entropy(s,alpha=1.0,K=None,prior=None):
 b=s.encode(); uniq=sorted(set(b)); K=K or len(uniq)
 trans=defaultdict(Counter); totals=Counter()
 for a,c in zip(b,b[1:]): trans[a][c]+=1;totals[a]+=1
 total=sum(totals.values()); H=0
 for a,cnt in trans.items():
  denom=totals[a]+alpha*K; h=0
  # all K symbols: for candidate alphabet uniq if K=len uniq
  symbols=uniq if K==len(uniq) else range(K)
  for c in symbols:
   p=(cnt.get(c,0)+alpha)/denom; h-=p*math.log2(p)
  H += (totals[a]/total)*h
 return H

def make(chars,counts,style):
 if style=='block': return ''.join(c*n for c,n in zip(chars,counts))
 if style=='roundrobin':
  rem=list(counts);out=[]
  while sum(rem):
   for i,c in enumerate(chars):
    if rem[i]:out.append(c);rem[i]-=1
  return ''.join(out)
 lst=list(''.join(c*n for c,n in zip(chars,counts)));rng.shuffle(lst);return ''.join(lst)
for u,counts in [(9,[2]*7+[1]*2),(10,[2]*6+[1]*4),(10,[7]+[1]*9),(9,[8]+[1]*8)]:
 for style in ['block','roundrobin','shuffle']:
  vals=[make(rng.sample(string.ascii_uppercase,u),counts,style) for _ in range(5)]
  print(u,counts,style,[round(smoothed_cond_entropy(v),3) for v in vals],[round(smoothed_cond_entropy(v,K=26),3) for v in vals])
PY
"}

