from collections import Counter,defaultdict
rng=random.Random(0)
def H(s,alpha,Kmode='u'):
 b=s.encode(); uniq=sorted(set(b)); K=len(uniq) if Kmode=='u' else Kmode
 trans=defaultdict(Counter);tot=Counter()
 for a,c in zip(b,b[1:]):trans[a][c]+=1;tot[a]+=1
 total=sum(tot.values());out=0
 symbols=uniq if Kmode=='u' else list(range(Kmode))
 # for K numeric symbols are byte values not 0..K for upper; use all byte values 0..255 if K=256 else uniq extended irrelevant alpha only in denom and unseen entropy term: unseen count=K-len(cnt)
 for a,cnt in trans.items():
  denom=tot[a]+alpha*K;h=0
  if Kmode=='u':
   for c in symbols:
    p=(cnt.get(c,0)+alpha)/denom;h-=p*math.log2(p)
  else:
   for c,ct in cnt.items():
    p=(ct+alpha)/denom;h-=p*math.log2(p)
   unseen=K-len(cnt);p=alpha/denom;h-=unseen*p*math.log2(p)
  out+=(tot[a]/total)*h
 return out

def make(chars,counts,style):
 if style=='block':return ''.join(c*n for c,n in zip(chars,counts))
