for cname,(trans,tot,start) in corpora.items():
 total_start=sum(start.values())
 for A in [1,10,100,1000]:
  # static: alpha_ab = A * p(b|a) where p from corpus conditional with fallback global? Use (count + 0.01?) Let's define base count = A * (trans[a][b]/tot[a]) if tot else A/256
  def make_score(adapt,A=A,trans=trans,tot=tot,start=start):
   def score(s):
    b=s.encode(); ll=0.0
    # start with global start prob smoothed as A? include as log((startcount scaled?) Use start prob from corpus p_start with smoothing 1/256 mixture: p=(start[b0]/total_start)
    pstart=(start[b[0]]+0.1)/(total_start+25.6) if b else 1
    ll+=math.log(pstart)
    seen=defaultdict(Counter); seentot=Counter()
    for a,c in zip(b,b[1:]):
     base = (A*(trans[a][c]/tot[a])) if tot[a]>0 else (A/256)
     # For unseen in corpus conditional, base=0 -> use a tiny floor via mixing global: add A*0.001/256? Keep: base = max(base, A*1e-5)
     base=max(base,A*1e-6)
     if adapt:
      p=(base+seen[a][c])/(A+seentot[a])
      seen[a][c]+=1;seentot[a]+=1
     else:
      p=base/A
     ll+=math.log(p)
    return ll/max(1,len(b))
   return score
  evalscore(f'{cname} static A{A}',make_score(False))
  evalscore(f'{cname} adapt A{A}',make_score(True))
 # uniform adapt (no corpus) per predecessor alpha=1 over K=95/256: base A/K with A=K gives alpha1
 for K in [62,95,256]:
  def uscore(s,K=K):
   b=s.encode();ll=math.log(1/K);seen=defaultdict(Counter);seentot=Counter()
   for a,c in zip(b,b[1:]):
    p=(1+seen[a][c])/(K+seentot[a]);ll+=math.log(p);seen[a][c]+=1;seentot[a]+=1
   return ll/max(1,len(b))
  evalscore(f'{cname} uniform-adapt K{K}',uscore)
