// Randomness classification for captured groups.
//
// The reference behaviour was explored by querying the program's public
// CLI: an additional regex pattern with one capture group reports the
// captured value only when it is deemed "random".  A broad, stratified
// set of synthetic strings was labelled that way during development and
// a decision tree was trained on byte-level summary features of the
// strings (length, distinct-byte counts, entropies, character-class
// proportions and transitions, sequential/keyboard runs, and a Markov
// transition score).  The resulting tree is stored in `tree_data.rs`
// and evaluated here; a few exact boundary behaviours observed from
// the CLI are handled as explicit rules first.

use crate::markov_data::{MARKOV_START, MARKOV_TOT, MARKOV_TOTAL_STARTS, MARKOV_TRANS};
use crate::tree_data::TREE_NODES;
use std::collections::HashMap;

pub fn is_random(secret: &[u8]) -> bool {
    if secret.len() > 170 {
        return true;
    }
    if secret.len() <= 2 {
        return true;
    }
    if secret.iter().all(|&b| b == secret[0]) {
        return secret == b"999";
    }
    let feats = features(secret);
    let mut node = 0usize;
    loop {
        let (feat, thr, left, right, pred) = TREE_NODES[node];
        if feat < 0 {
            return pred;
        }
        node = if feats[feat as usize] <= thr { left as usize } else { right as usize };
    }
