    for w in b.windows(2) {
        cur2 = if w[0] == w[1] { cur2 + 1 } else { 1 };
        maxsame = maxsame.max(cur2);
    }
    out[60] = maxsame as f64;
    let (mut kbtot, mut kbadj) = (0usize, 0usize);
    for w in b.windows(2) {
        if let (Some(pa), Some(pc)) = (kb_pos(w[0]), kb_pos(w[1])) {
