{"command":"cat > src/randomness.rs << 'RS'
// Randomness classification for captured groups.
//
// The reference behaviour was explored by querying the program's public
// CLI: an additional regex pattern with one capture group reports the
// captured value only when it is deemed "random".  A broad, stratified
// set of synthetic strings was labelled that way during development and
// a decision tree was trained on byte-level summary features of the
// strings (length, distinct-byte counts, entropies, character-class
// proportions and transitions, sequential/keyboard runs, and a Markov
// transition score).  The resulting tree is stored in `tree_data.rs`
// and evaluated here; a few exact boundary behaviours observed from
// the CLI are handled as explicit rules first.

use crate::markov_data::{MARKOV_START, MARKOV_TOT, MARKOV_TOTAL_STARTS, MARKOV_TRANS};
use crate::tree_data::TREE_NODES;
use std::collections::HashMap;

pub fn is_random(secret: &[u8]) -> bool {
    if secret.len() > 170 {
        return true;
    }
    if secret.len() <= 2 {
        return true;
    }
    if secret.iter().all(|&b| b == secret[0]) {
        return secret == b"999";
    }
    let feats = features(secret);
    let mut node = 0usize;
    loop {
        let (feat, thr, left, right, pred) = TREE_NODES[node];
        if feat < 0 {
            return pred;
        }
        node = if feats[feat as usize] <= thr { left as usize } else { right as usize };
    }
}

fn classof(x: u8) -> usize {
    if x.is_ascii_lowercase() {
        0
    } else if x.is_ascii_uppercase() {
        1
    } else if x.is_ascii_digit() {
        2
    } else {
        3
    }
}

fn entropy(counts: &HashMap<u8, usize>, total: usize) -> f64 {
    if total == 0 {
        return 0.0;
    }
    let t = total as f64;
    -counts
        .values()
        .map(|&c| {
            let p = c as f64 / t;
            p * p.log2()
        })
        .sum::<f64>()
}

fn kb_pos(x: u8) -> Option<(i32, i32)> {
    if x >= 128 {
        return None;
    }
    let c = (x as char).to_ascii_lowercase();
    let rows = ["1234567890", "qwertyuiop", "asdfghjkl", "zxcvbnm"];
    for (r, row) in rows.iter().enumerate() {
        if let Some(col) = row.find(c) {
            return Some((r as i32, col as i32));
        }
    }
    None
}

fn utf8_ignore(b: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut rest = b;
    loop {
        match std::str::from_utf8(rest) {
            Ok(s) => {
                out.extend_from_slice(s.as_bytes());
                break;
            }
            Err(e) => {
                let valid = e.valid_up_to();
                out.extend_from_slice(&rest[..valid]);
                let skip = e.error_len().map(|l| l as usize).unwrap_or(rest.len() - valid);
                if valid + skip >= rest.len() {
                    break;
                }
                rest = &rest[valid + skip..];
            }
        }
    }
    out
}

fn markov_score(secret: &[u8]) -> f64 {
    let b = utf8_ignore(secret);
    if b.is_empty() {
        return 0.0;
    }
    let alpha = 1.0f64;
    let start_count = |x: u8| -> f64 {
        if x.is_ascii_lowercase() {
            MARKOV_START[(x - b'a') as usize] as f64
        } else {
            0.0
        }
    };
    let mut sum = ((start_count(b[0]) + alpha) / (MARKOV_TOTAL_STARTS as f64 + alpha * 256.0)).ln();
    let mut nvals = 1usize;
    for pair in b.windows(2) {
        let (a, c) = (pair[0], pair[1]);
        let (cnt, tot) = if a.is_ascii_lowercase() {
            let ai = (a - b'a') as usize;
            let cnt = if c.is_ascii_lowercase() {
                MARKOV_TRANS[ai][(c - b'a') as usize] as f64
            } else {
                0.0
            };
            (cnt, MARKOV_TOT[ai] as f64)
        } else {
            (0.0, 0.0)
        };
        sum += ((cnt + alpha) / (tot + alpha * 256.0)).ln();
        nvals += 1;
    }
    sum / nvals as f64
}

fn subseq_feats(b: &[u8], pred: impl Fn(u8) -> bool) -> [f64; 3] {
    let seq: Vec<u8> = b.iter().copied().filter(|&x| pred(x)).collect();
    if seq.len() < 2 {
        return [0.0, 0.0, 0.0];
    }
    let diffs: Vec<i32> = seq.windows(2).map(|w| w[1] as i32 - w[0] as i32).collect();
    let d = diffs.len() as f64;
    [
        diffs.iter().filter(|&&x| x == 1).count() as f64 / d,
        diffs.iter().filter(|&&x| x == -1).count() as f64 / d,
        diffs.iter().filter(|&&x| x.abs() == 1).count() as f64 / d,
    ]
}

fn features(b: &[u8]) -> [f64; 74] {
    let n = b.len();
    let mut out = [0.0f64; 74];
    if n == 0 {
        return out;
    }
    let nf = n as f64;
    let mut cnt: HashMap<u8, usize> = HashMap::new();
    for &x in b {
        *cnt.entry(x).or_default() += 1;
    }
    let u = cnt.len();
    let unih = entropy(&cnt, n);
    let mut big: HashMap<(u8, u8), usize> = HashMap::new();
    for w in b.windows(2) {
        *big.entry((w[0], w[1])).or_default() += 1;
    }
    let bigh = if n > 1 {
        let total = (n - 1) as f64;
        -big.values()
            .map(|&c| {
                let p = c as f64 / total;
                p * p.log2()
            })
            .sum::<f64>()
    } else {
        0.0
    };
    // conditional entropy H(next | prev)
    let mut by: HashMap<u8, HashMap<u8, usize>> = HashMap::new();
    for w in b.windows(2) {
        *by.entry(w[0]).or_default().entry(w[1]).or_default() += 1;
    }
    let mut condh = 0.0;
    if n > 1 {
        for counter in by.values() {
            let tot: usize = counter.values().sum();
            condh += (tot as f64 / (n - 1) as f64) * entropy(counter, tot);
        }
    }
    let mut prevcnt: HashMap<u8, usize> = HashMap::new();
    if n > 1 {
        for &x in &b[..n - 1] {
            *prevcnt.entry(x).or_default() += 1;
        }
    }
    let prevh = if n > 1 { entropy(&prevcnt, n - 1) } else { 0.0 };
    let denom = if n > 1 { (n - 1) as f64 } else { 1.0 };
    let transdiff = if n > 1 {
        b.windows(2).filter(|w| w[0] != w[1]).count() as f64 / denom
    } else {
        0.0
    };
    let classtr = if n > 1 {
        b.windows(2).filter(|w| classof(w[0]) != classof(w[1])).count() as f64 / denom
    } else {
        0.0
    };
    let lower = b.iter().filter(|x| x.is_ascii_lowercase()).count() as f64 / nf;
    let upper = b.iter().filter(|x| x.is_ascii_uppercase()).count() as f64 / nf;
    let digit = b.iter().filter(|x| x.is_ascii_digit()).count() as f64 / nf;
    let symb = 1.0 - lower - upper - digit;
    let absdiff = if n > 1 {
        b.windows(2).map(|w| (w[1] as i32 - w[0] as i32).abs() as f64).sum::<f64>() / denom
    } else {
        0.0
    };
    let runs = 1 + b.windows(2).filter(|w| w[0] != w[1]).count();
    let meanb = b.iter().map(|&x| x as f64).sum::<f64>() / nf;
    let stdb = (b.iter().map(|&x| (x as f64 - meanb).powi(2)).sum::<f64>() / nf).sqrt();
    let base = [
        nf,
        u as f64 / nf,
        u as f64,
        unih,
        bigh,
        condh,
        bigh - prevh,
        if n > 1 { big.len() as f64 / denom } else { 0.0 },
        transdiff,
        classtr,
        lower,
        upper,
        digit,
        symb,
        absdiff,
        runs as f64 / nf,
        *cnt.values().max().unwrap() as f64 / nf,
        *b.iter().min().unwrap() as f64,
        *b.iter().max().unwrap() as f64,
        meanb,
        stdb,
        b.iter().filter(|&&x| matches!(x.to_ascii_lowercase(), b'a' | b'e' | b'i' | b'o' | b'u')).count() as f64 / nf,
    ];
    out[..22].copy_from_slice(&base);
    out[22] = b.iter().filter(|&&x| x == 122).count() as f64;
    out[23] = b.iter().filter(|&&x| x == 90).count() as f64;
    out[24] = b.iter().filter(|&&x| x == 57).count() as f64;
    out[25] = if b.contains(&122) { 1.0 } else { 0.0 };
    out[26] = if b.contains(&90) { 1.0 } else { 0.0 };
    // class transitions 27..43
    if n > 1 {
        for w in b.windows(2) {
            out[27 + classof(w[0]) * 4 + classof(w[1])] += 1.0 / denom;
        }
    }
    out[43] = if b.iter().all(|x| x.is_ascii_lowercase()) { 1.0 } else { 0.0 };
    out[44] = if b.iter().all(|x| x.is_ascii_uppercase()) { 1.0 } else { 0.0 };
    out[45] = if b.iter().all(|x| x.is_ascii_digit()) { 1.0 } else { 0.0 };
    out[46] = if b.iter().all(|&x| (x as char) != '\0' && "0123456789abcdef".contains(x as char)) { 1.0 } else { 0.0 };
    out[47] = if b.iter().all(|&x| "0123456789ABCDEF".contains(x as char)) { 1.0 } else { 0.0 };
    out[48] = if b.iter().all(|x| x.is_ascii_alphanumeric()) { 1.0 } else { 0.0 };
    // more features
    let mut tri: HashMap<(u8, u8, u8), usize> = HashMap::new();
    for w in b.windows(3) {
        *tri.entry((w[0], w[1], w[2])).or_default() += 1;
    }
    out[49] = if n > 2 { tri.len() as f64 / (n - 2) as f64 } else { 0.0 };
    out[50] = big.values().filter(|&&c| c > 1).map(|&c| (c - 1) as f64).sum();
    out[51] = classof(b[0]) as f64;
    out[52] = classof(b[n - 1]) as f64;
    let diffs: Vec<i32> = b.windows(2).map(|w| w[1] as i32 - w[0] as i32).collect();
    if n > 1 {
        out[53] = diffs.iter().filter(|&&d| d == 1).count() as f64 / denom;
        out[54] = diffs.iter().filter(|&&d| d == -1).count() as f64 / denom;
        out[55] = diffs.iter().filter(|&&d| d.abs() == 1).count() as f64 / denom;
    }
    let longest = |want: i32| -> f64 {
        let (mut best, mut cur) = (1usize, 1usize);
        for &d in &diffs {
            cur = if d == want { cur + 1 } else { 1 };
            best = best.max(cur);
        }
        best as f64
    };
    out[56] = longest(1);
    out[57] = longest(-1);
    let (mut maxdig, mut cur) = (0usize, 0usize);
    for &x in b {
        cur = if x.is_ascii_digit() { cur + 1 } else { 0 };
        maxdig = maxdig.max(cur);
    }
    out[58] = maxdig as f64;
    out[59] = b.iter().rev().take_while(|x| x.is_ascii_digit()).count() as f64;
    let (mut maxsame, mut cur2) = (1usize, 1usize);
    for w in b.windows(2) {
        cur2 = if w[0] == w[1] { cur2 + 1 } else { 1 };
        maxsame = maxsame.max(cur2);
    }
    out[60] = maxsame as f64;
    let (mut kbtot, mut kbadj) = (0usize, 0usize);
    for w in b.windows(2) {
        if let (Some(pa), Some(pc)) = (kb_pos(w[0]), kb_pos(w[1])) {
            kbtot += 1;
            if (pa.0 - pc.0).abs().max((pa.1 - pc.1).abs()) <= 1 {
                kbadj += 1;
            }
        }
    }
    out[61] = if kbtot > 0 { kbadj as f64 / kbtot as f64 } else { 0.0 };
    out[62] = markov_score(b);
    let sl = subseq_feats(b, |x| x.is_ascii_lowercase());
    let su = subseq_feats(b, |x| x.is_ascii_uppercase());
    let sd = subseq_feats(b, |x| x.is_ascii_digit());
    out[63..66].copy_from_slice(&sl);
    out[66..69].copy_from_slice(&su);
    out[69..72].copy_from_slice(&sd);
    if n > 1 {
        out[72] = diffs.iter().filter(|&&d| d >= 0).count() as f64 / denom;
        out[73] = diffs.iter().filter(|&&d| d <= 0).count() as f64 / denom;
    }
    out
}
