s=s.replace('use std::io::{self, BufRead, BufReader, Read, Write};','use std::io::{self, BufRead, BufReader, IsTerminal, Read, Write};')
old='''fn parse_cli() -> Cli {
    let matches = build_cli().get_matches();'''
new='''fn parse_cli() -> Cli {
    let matches = match build_cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // The reference binary was built with an older clap whose
            // "smart usage" for an unknown argument with a suggested
            // user-defined long flag lists every argument as a choice.
            // Reproduce that usage line; all other errors are left to
            // clap's own rendering.
            let suggested_user_arg = e.kind() == ErrorKind::UnknownArgument
                && e.context().any(|(k, v)| {
                    k == ContextKind::SuggestedArg
                        && matches!(v, ContextValue::String(s) if matches!(s.as_str(), "--install-pre-commit" | "--strict-ignore" | "--only-matching" | "--additional-pattern"))
                });
            if suggested_user_arg {
                let rendered = e.render();
                let mut text = if io::stderr().is_terminal() {
                    rendered.ansi().to_string()
                } else {
                    rendered.to_string()
                };
                if let Some(u) = text.find("Usage:") {
                    let line_end = text[u..].find('\\n').map(|i| u + i).unwrap_or(text.len());
                    let choice = "<--install-pre-commit|--strict-ignore|--only-matching|--additional-pattern <ADDITIONAL_PATTERNS>|Source files>";
                    // Keep any styling up to the end of the binary name
                    // (the second reset sequence on the usage line), then
                    // append the choice list as plain text.
                    let resets: Vec<usize> = text[u..line_end]
                        .match_indices("\\u{1b}[0m")
                        .map(|(i, m)| u + i + m.len())
                        .collect();
                    if resets.len() >= 2 {
                        let keep = resets[1];
                        text = format!("{} {}{}", &text[..keep], choice, &text[line_end..]);
                    } else if let Some(sp) = text[u..line_end].find(' ') {
                        // Plain rendering: "Usage: {bin} ..."
                        let after = &text[u + sp + 1..line_end];
                        let bin = after.split_whitespace().next().unwrap_or("ripsecrets");
                        text = format!("{}Usage: {} {}{}", &text[..u], bin, choice, &text[line_end..]);
                    }
                }
                eprint!("{}", text);
                std::process::exit(e.exit_code());
            }
            e.exit()
        }
    };'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
