for args in "--additional-patter x" "--only-matching --additional-patter x" "--strict-ignore --only" "--ver" "--unknown" "-x"; do echo "ARGS $args"; diff <(/tmp/refbin/executable $args 2>&1; echo rc:$?) <(./executable $args 2>&1; echo rc:$?) && echo SAME; done
TERM=xterm-256color script -qec "/workspace/executable --additional-patter x" /dev/null > /tmp/new_tty.txt; TERM=xterm-256color script -qec "/tmp/refbin/executable --additional-patter x" /dev/null > /tmp/ref_tty.txt; diff /tmp/ref_tty.txt /tmp/new_tty.txt && echo TTY_SAME
"}

