{"command":"cat > /tmp/igtest/src/main.rs << 'RS'
use ignore::{WalkBuilder, WalkState};
use std::sync::atomic::{AtomicUsize, Ordering};
fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let first = if args.is_empty() { ".".to_string() } else { args[0].clone() };
    let mut b = WalkBuilder::new(&first);
    for p in args.iter().skip(1) { b.add(p); }
    let cwd = std::env::current_dir().unwrap();
    let si = cwd.join(".secretsignore");
    if si.exists() { b.add_custom_ignore_filename(si.as_os_str()); }
    let count = AtomicUsize::new(0);
    b.build_parallel().run(|| {
        let c = count.fetch_add(1, Ordering::SeqCst);
        eprintln!("visitor built {}", c);
        Box::new(|_| WalkState::Continue)
    });
    eprintln!("total visitors {}", count.load(Ordering::SeqCst));
}
RS
cd /tmp/igtest && cargo build --offline --quiet
for setup in flat sub explicit; do td=$(mktemp -d); printf 'x\n' > $td/a.txt; mkdir -p $td/sub; printf 'x\n' > $td/sub/b.txt; printf 'a.txt\n' > $td/.secretsignore; echo "== $setup"; case $setup in flat) (cd $td && /tmp/igtest/target/debug/igtest 2>&1 | tail -3);; sub) (cd $td && /tmp/igtest/target/debug/igtest sub 2>&1 | tail -3);; explicit) (cd $td && /tmp/igtest/target/debug/igtest a.txt 2>&1 | tail -3);; esac; rm -rf $td; done"}

